(function () {
'use strict';
var EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/;
var PHONE_RE = /^[0-9 +()\-]{7,20}$/;
function fieldError(field) {
var value = (field.value || '').trim();
var type = (field.getAttribute('type') || field.tagName).toLowerCase();
var label = labelFor(field);
if (field.type === 'checkbox') {
return field.required && !field.checked ? label + ' is required.' : '';
}
if (field.required && value === '') {
return label + ' is required.';
}
if (value === '') {
return '';
}
if (type === 'email' && !EMAIL_RE.test(value)) {
return 'Please enter a valid email address.';
}
if (type === 'tel' && !PHONE_RE.test(value)) {
return 'Please enter a valid phone number.';
}
if (type === 'date' && field.name === 'date_of_birth') {
if (new Date(value) > new Date()) return 'Date of birth cannot be in the future.';
}
if (type === 'file' && field.files && field.files[0] && field.files[0].size > 5 * 1024 * 1024) {
return 'File is too large (max 5 MB).';
}
return '';
}
function labelFor(field) {
var el = field.closest('.form-group');
var lab = el ? el.querySelector('label') : null;
var text = lab ? lab.textContent.replace('*', '').replace('(required)', '').trim() : 'This field';
return text.replace(/\s*\(.*?\)\s*$/, '').trim() || 'This field';
}
function errorSlot(field) {
var group = field.closest('.form-group');
if (!group) return null;
var slot = group.querySelector('.field-error');
if (!slot) {
slot = document.createElement('p');
slot.className = 'field-error';
slot.id = (field.id || field.name) + '_err';
slot.hidden = true;
group.appendChild(slot);
}
return slot;
}
function showFieldError(field, message) {
var slot = errorSlot(field);
if (!slot) return;
if (message) {
slot.textContent = message;
slot.hidden = false;
field.setAttribute('aria-invalid', 'true');
field.setAttribute('aria-describedby', slot.id);
var g = field.closest('.form-group');
if (g) g.classList.add('has-error');
} else {
slot.textContent = '';
slot.hidden = true;
field.removeAttribute('aria-invalid');
field.removeAttribute('aria-describedby');
var g2 = field.closest('.form-group');
if (g2) g2.classList.remove('has-error');
}
}
function validatableFields(form) {
return Array.prototype.filter.call(
form.querySelectorAll('input, select, textarea'),
function (f) {
return f.type !== 'hidden' && f.name !== 'website' && !f.disabled;
}
);
}
function validateForm(form) {
var firstBad = null;
validatableFields(form).forEach(function (f) {
var msg = fieldError(f);
showFieldError(f, msg);
if (msg && !firstBad) firstBad = f;
});
return firstBad;
}
function banner(form, status, message) {
var box = form.querySelector('.form-result');
if (!box) {
box = document.createElement('div');
box.className = 'form-result';
form.insertBefore(box, form.firstChild);
}
if (!status) {
box.innerHTML = '';
return box;
}
var isError = status === 'error';
box.innerHTML =
'<div class="alert alert-' + (isError ? 'error' : 'success') + '"' +
' role="' + (isError ? 'alert' : 'status') + '"' +
' aria-live="' + (isError ? 'assertive' : 'polite') + '">' +
'<span class="sr-only">' + (isError ? 'Error: ' : 'Success: ') + '</span>' +
escapeHtml(message) + '</div>';
return box;
}
function escapeHtml(s) {
var d = document.createElement('div');
d.textContent = s == null ? '' : String(s);
return d.innerHTML;
}
function setLoading(form, on, label) {
var btn = form.querySelector('button[type=submit], input[type=submit]');
if (!btn) return;
if (on) {
btn.dataset.originalText = btn.dataset.originalText || btn.innerHTML;
btn.disabled = true;
btn.setAttribute('aria-busy', 'true');
btn.innerHTML = '<span class="spinner" aria-hidden="true"></span>' +
escapeHtml(label || 'Sending…');
form.classList.add('is-submitting');
} else {
btn.disabled = false;
btn.removeAttribute('aria-busy');
if (btn.dataset.originalText) btn.innerHTML = btn.dataset.originalText;
form.classList.remove('is-submitting');
}
}
function progressBar(form) {
var bar = form.querySelector('.upload-progress');
if (!bar) {
bar = document.createElement('div');
bar.className = 'upload-progress';
bar.hidden = true;
bar.innerHTML =
'<div class="upload-progress-track">' +
'  <div class="upload-progress-fill" role="progressbar" aria-valuemin="0" aria-valuemax="100"' +
'       aria-valuenow="0" aria-label="Upload progress"></div>' +
'</div>' +
'<span class="upload-progress-text">Uploading… 0%</span>';
var btn = form.querySelector('button[type=submit]');
if (btn && btn.parentNode) btn.parentNode.insertBefore(bar, btn);
else form.appendChild(bar);
}
return bar;
}
function setProgress(form, pct, done) {
var bar = progressBar(form);
var fill = bar.querySelector('.upload-progress-fill');
var text = bar.querySelector('.upload-progress-text');
bar.hidden = false;
fill.style.width = pct + '%';
fill.setAttribute('aria-valuenow', String(pct));
text.textContent = done ? 'Processing…' : 'Uploading… ' + pct + '%';
}
function hideProgress(form) {
var bar = form.querySelector('.upload-progress');
if (bar) bar.hidden = true;
}
function hasFiles(form) {
return Array.prototype.some.call(form.querySelectorAll('input[type=file]'), function (f) {
return f.files && f.files.length > 0;
});
}
function showSuccess(form, data) {
var custom = form.getAttribute('data-success-template');
if (custom === 'application' && data.app_number) {
form.innerHTML =
'<div class="form-success" role="status" aria-live="polite" tabindex="-1">' +
'  <div class="form-success-icon" aria-hidden="true">✓</div>' +
'  <h3>Application Submitted</h3>' +
'  <p>Thank you — we\'ve received the application for <strong>' +
escapeHtml(data.student_name) + '</strong>' +
(data.class_applying ? ' (' + escapeHtml(data.class_applying) + ')' : '') + '.</p>' +
'  <p class="app-number-box">Your application number<strong>' +
escapeHtml(data.app_number) + '</strong></p>' +
'  <p class="form-hint">Save this number — you\'ll need it to track your application.' +
(data.doc_count ? ' ' + data.doc_count + ' document(s) uploaded.' : '') + '</p>' +
'  <div class="form-success-actions">' +
'    <a href="' + escapeHtml(data.status_url) + '" class="btn btn-dark">Track Application</a>' +
'    <a href="' + escapeHtml(data.print_url) + '" class="btn btn-outline" target="_blank" rel="noopener">Print Application</a>' +
'  </div>' +
'</div>';
} else {
form.innerHTML =
'<div class="form-success" role="status" aria-live="polite" tabindex="-1">' +
'  <div class="form-success-icon" aria-hidden="true">✓</div>' +
'  <h3>Thank you!</h3>' +
'  <p>' + escapeHtml(data.message || 'Your message has been sent.') + '</p>' +
'</div>';
}
var panel = form.querySelector('.form-success');
if (panel) {
panel.focus();
panel.scrollIntoView({ block: 'center', behavior: 'smooth' });
}
}
document.addEventListener('DOMContentLoaded', function () {
document.querySelectorAll('form[data-ajax]').forEach(function (form) {
form.setAttribute('novalidate', 'novalidate');
validatableFields(form).forEach(function (f) {
f.addEventListener('blur', function () {
showFieldError(f, fieldError(f));
});
f.addEventListener('input', function () {
if (f.getAttribute('aria-invalid') === 'true') {
var msg = fieldError(f);
if (!msg) showFieldError(f, '');
}
});
if (f.type === 'file') {
f.addEventListener('change', function () {
showFieldError(f, fieldError(f));
});
}
});
form.addEventListener('submit', function (e) {
e.preventDefault();
var firstBad = validateForm(form);
if (firstBad) {
banner(form, 'error', 'Please correct the highlighted fields below.');
firstBad.focus();
firstBad.scrollIntoView({ block: 'center', behavior: 'smooth' });
return;
}
banner(form, null, '');
var uploading = hasFiles(form);
setLoading(form, true, form.getAttribute('data-loading-text') || 'Sending…');
var xhr = new XMLHttpRequest();
var action = form.getAttribute('data-ajax-action') || form.action;
xhr.open('POST', action, true);
xhr.setRequestHeader('X-Requested-With', 'XMLHttpRequest');
if (uploading && xhr.upload) {
xhr.upload.addEventListener('progress', function (evt) {
if (!evt.lengthComputable) return;
var pct = Math.round((evt.loaded / evt.total) * 100);
setProgress(form, pct, pct >= 100);
});
}
xhr.onload = function () {
setLoading(form, false);
hideProgress(form);
var data;
try {
data = JSON.parse(xhr.responseText);
} catch (err) {
form.removeAttribute('data-ajax');
form.submit();
return;
}
var tok = form.querySelector('input[name=csrf_token]');
if (tok && data.csrf) tok.value = data.csrf;
if (data.status === 'success') {
showSuccess(form, data);
return;
}
if (data.errors) {
Object.keys(data.errors).forEach(function (key) {
var field = form.querySelector('[name="' + key + '"]');
if (field) showFieldError(field, data.errors[key]);
});
var firstServerBad = form.querySelector('[aria-invalid=true]');
if (firstServerBad) {
firstServerBad.focus();
firstServerBad.scrollIntoView({ block: 'center', behavior: 'smooth' });
}
}
var box = banner(form, 'error', data.message || 'Something went wrong. Please try again.');
if (!data.errors || !Object.keys(data.errors).length) {
box.scrollIntoView({ block: 'center', behavior: 'smooth' });
}
};
xhr.onerror = function () {
setLoading(form, false);
hideProgress(form);
banner(form, 'error',
'Could not reach the server. Check your connection and try again.')
.scrollIntoView({ block: 'center', behavior: 'smooth' });
};
xhr.timeout = 60000;
xhr.ontimeout = function () {
setLoading(form, false);
hideProgress(form);
banner(form, 'error', 'The request took too long. Please try again.');
};
xhr.send(new FormData(form));
});
});
});
})();